/bin/zsh -lc "PYTHONDONTWRITEBYTECODE=1 .venv/bin/python -B -c 'import sys, pathlib, json, ast, hashlib
sys.path.insert(0,'\\''src'\\'')
import pandas as pd
import sgen004_envelope as ev
root=pathlib.Path('\\''.'\\'')
e=json.loads((root/'\\''generations/pgen003/eligibility_recompute_v1.json'\\'').read_text())
cohort=pd.read_csv(root/'\\''lock_s/cohort.csv'\\'',dtype=str)
models=pd.read_csv(root/'\\''data/passports_model_list_20260921.csv'\\'',dtype=str).fillna('\\'''\\'')
import re
key={}
for _,r in models.iterrows():
 for cand in [r['\\''model_name'\\'']]+re.split(r'\\''[|;]'\\'',str(r.get('\\''synonyms'\\'') or '\\'''\\'')):
  k=ev.norm(cand)
  if k:key.setdefault(k,set()).add(str(r['\\''patient_id'\\'']))
cpatients=set()
for s in cohort.sample_ID:
 pats=key.get(ev.norm(s),set());assert len(pats)==1
 cpatients.update(pats)
broad7={'\\''ACH-000048'\\'','\\''ACH-000108'\\'','\\''ACH-000178'\\'','\\''ACH-001418'\\'','\\''ACH-002958'\\'','\\''ACH-003040'\\'','\\''ACH-003052'\\''}
md=e['\\''matched_detail'\\'']
overlap={v['\\''patient_id'\\''] for v in md.values()} & cpatients
exposed={v['\\''patient_id'\\''] for v in md.values() if set(v['\\''broad_id'\\'']) & broad7}
elig={v['\\''patient_id'\\''] for v in md.values()}-overlap-exposed
lines=[k for k,v in md.items() if v['\\''patient_id'\\''] in elig]
print('\\''independent_exclusions_and_totals'\\'',{'\\''c_patients'\\'':len(cpatients),'\\''overlap'\\'':sorted(overlap),'\\''exposed_patients'\\'':sorted(exposed),'\\''eligible_patients'\\'':len(elig),'\\''eligible_lines'\\'':len(lines),'\\''files'\\'':sum(md[k]['\\''files'\\''] for k in lines)})
res=json.loads((root/'\\''lock_s/results/external_v1.json'\\'').read_text())
want3=[f\"{res['\\''primary'\\'']['\\''estimate'\\'']:.3f}\",f\"{res['\\''primary'\\'']['\\''ci95_donor_percentile'\\''][0]:.3f}\",f\"{res['\\''primary'\\'']['\\''ci95_donor_percentile'\\''][1]:.3f}\"]
bad='\\''| Primary (confirmatory207 / mean_abs_delta / base_strength) | decision | -0.175 | donor 95% [-0.146, -0.114] | yes | **yes (BOUND)** |'\\''
print('\\''swapped_primary_estimate_and_ci_still_passes'\\'',any(('\\''primary'\\'' in ln.lower()) and all(s in ln for s in want3) for ln in bad.splitlines()))
for f in ['\\''pyproject.toml'\\'','\\''uv.lock'\\'']:
 print('\\''fresh_vs_current'\\'',f,(root/f).read_bytes()==(pathlib.Path('\\''/tmp/cdrsi_fresh'\\'')/f).read_bytes())
audit=json.loads((root/'\\''generations/sgen005/synthetic_use_audit.json'\\'').read_text())
for row in audit['\\''mechanical_code_diagnostics'\\'']:
 for ref in row['\\''artifacts'\\'']:
  if '\\'':'\\'' in ref:
   p,k=ref.split('\\'':'\\'',1)
   print('\\''audit_field'\\'',ref,k in json.loads((root/p).read_text()))
  else:print('\\''audit_path'\\'',ref,(root/ref).exists())
'"

